@pytest.mark.parametrize('orient,expected', [('split', '{\n    "columns":[\n        "a",\n        "b"\n    ],\n    "index":[\n        0,\n        1\n    ],\n    "data":[\n        [\n            "foo",\n            "bar"\n        ],\n        [\n            "baz",\n            "qux"\n        ]\n    ]\n}'), ('records', '[\n    {\n        "a":"foo",\n        "b":"bar"\n    },\n    {\n        "a":"baz",\n        "b":"qux"\n    }\n]'), ('index', '{\n    "0":{\n        "a":"foo",\n        "b":"bar"\n    },\n    "1":{\n        "a":"baz",\n        "b":"qux"\n    }\n}'), ('columns', '{\n    "a":{\n        "0":"foo",\n        "1":"baz"\n    },\n    "b":{\n        "0":"bar",\n        "1":"qux"\n    }\n}'), ('values', '[\n    [\n        "foo",\n        "bar"\n    ],\n    [\n        "baz",\n        "qux"\n    ]\n]'), ('table', '{\n    "schema":{\n        "fields":[\n            {\n                "name":"index",\n                "type":"integer"\n            },\n            {\n                "name":"a",\n                "type":"string"\n            },\n            {\n                "name":"b",\n                "type":"string"\n            }\n        ],\n        "primaryKey":[\n            "index"\n        ],\n        "pandas_version":"0.20.0"\n    },\n    "data":[\n        {\n            "index":0,\n            "a":"foo",\n            "b":"bar"\n        },\n        {\n            "index":1,\n            "a":"baz",\n            "b":"qux"\n        }\n    ]\n}')])
def test_json_indent_all_orients(self, orient, expected):
    df = pd.DataFrame([['foo', 'bar'], ['baz', 'qux']], columns=['a', 'b'])
    result = df.to_json(orient=orient, indent=4)
    assert result == expected